const unsigned char *font8x16_glyph(unsigned cp) {
    if (cp >= 0x20 && cp < 0x7F) return glyphs[cp - 0x20].rows;
    unsigned lo = 0x5F, hi = sizeof(glyphs) / sizeof(glyphs[0]);
    while (lo < hi) {
        unsigned mid = (lo + hi) / 2;
        if (glyphs[mid].cp == cp) return glyphs[mid].rows;
        if (glyphs[mid].cp < cp) lo = mid + 1; else hi = mid;
    }
    return notdef;
}
